import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

/**
 * Generate a report of overdue invoices.
 * @param {Array} invoices - All invoices to check
 * @param {string} asOf - Date in YYYY-MM-DD format; invoices with dueDate < asOf are overdue
 * @returns {Array} Array of { number, customerId, dueDate, daysOverdue, due }, sorted by daysOverdue descending
 */
export function overdueInvoices(invoices, asOf) {
  // Filter for overdue invoices (issued or partially_paid, with dueDate before asOf)
  const overdue = (invoices || []).filter((inv) =>
    (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf
  );

  // Map to report format
  const result = overdue
    .map((inv) => {
      const dueResult = balanceDue(inv);
      const due = dueResult.ok ? dueResult.value : 0;
      const daysOverdue = daysBetween(inv.dueDate, asOf);

      return {
        number: inv.number,
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return result;
}

/**
 * Generate a VAT summary by rate for issued/partially_paid/paid invoices.
 * @param {Array} invoices - All invoices to summarize
 * @returns {Array} Array of { rate, base, vat }, sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = {}; // rate -> { base, vat }

  (invoices || []).forEach((inv) => {
    if (!['issued', 'partially_paid', 'paid'].includes(inv.status)) return;

    inv.lines?.forEach((line) => {
      const rate = line.vatRate;
      const lineTotal = line.qty * line.unitPrice;
      const discount = roundCents(lineTotal * (line.discountPercent || 0) / 100);
      const base = lineTotal - discount;
      const vatAmount = roundCents(base * rate / 100);

      if (!vatMap[rate]) {
        vatMap[rate] = { base: 0, vat: 0 };
      }
      vatMap[rate].base += base;
      vatMap[rate].vat += vatAmount;
    });
  });

  // Convert to array and sort by rate descending
  return Object.entries(vatMap)
    .map(([rate, { base, vat }]) => ({
      rate: Number(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

