  const r = vatSummary([partial.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 8500);
  assert.equal(r[0].vat, 1785);
});

test('vatSummary includes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const paid = recordPayment(issued.value, { amount: 10285, date: '2026-10-10' });

  const r = vatSummary([paid.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
});

test('vatSummary with multiple lines of same VAT rate', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
