  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 }, // 21%
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }, // 0%
    ],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = vatSummary([issued1.value, issued2.value]);
  assert.equal(r.length, 3);
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 17000); // 8500 + 8500
  assert.equal(r[0].vat, 3570); // 1785 + 1785
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 37);
  assert.equal(r[1].vat, 3); // 37 * 0.09 = 3.33 -> 3
  assert.equal(r[2].rate, 0);
  assert.equal(r[2].base, 60000);
  assert.equal(r[2].vat, 0);
});
